COMMENT ON COLUMN ee."fr_versions"."description" IS '需求描述';

COMMENT ON COLUMN ee."fr_versions"."type_code" IS '固定类型鉴别列，供组合FK校验，不是另一个可编辑属性';

CREATE TABLE ee."fr_uc_sources" (
