CREATE TABLE ee."project_subsystem_designs" (
  "project_id" uuid NOT NULL,
  "name" text NOT NULL,
  "current_version_id" uuid,
  "lock_version" bigint NOT NULL DEFAULT 0,
  "metadata" jsonb NOT NULL DEFAULT '{}'::jsonb,
  "created_by" uuid NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "updated_by" uuid NOT NULL,
  "updated_at" timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT "project_subsystem_designs_pk" PRIMARY KEY ("project_id"),
  CONSTRAINT "project_subsystem_designs_ck_0" CHECK ((length(btrim("name"))>0) IS TRUE),
  CONSTRAINT "project_subsystem_designs_ck_1" CHECK (("lock_version">=0) IS TRUE),
  CONSTRAINT "project_subsystem_designs_ck_2" CHECK ((jsonb_typeof("metadata")='object') IS TRUE)
);

COMMENT ON TABLE ee."project_subsystem_designs" IS '项目级子系统方案的稳定入口和当前生效版本指针。';

COMMENT ON COLUMN ee."project_subsystem_designs"."project_id" IS '项目';

COMMENT ON COLUMN ee."project_subsystem_designs"."name" IS '方案名称';

COMMENT ON COLUMN ee."project_subsystem_designs"."current_version_id" IS '当前采用的方案版本';

COMMENT ON COLUMN ee."project_subsystem_designs"."lock_version" IS '方案入口并发控制令牌';

COMMENT ON COLUMN ee."project_subsystem_designs"."metadata" IS '非核心扩展';

COMMENT ON COLUMN ee."project_subsystem_designs"."created_by" IS '创建人';

COMMENT ON COLUMN ee."project_subsystem_designs"."created_at" IS '创建时间';

COMMENT ON COLUMN ee."project_subsystem_designs"."updated_by" IS '最后修改人';

COMMENT ON COLUMN ee."project_subsystem_designs"."updated_at" IS '更新时间';

CREATE TABLE ee."subsystem_design_versions" (
  "id" uuid NOT NULL,
  "project_id" uuid NOT NULL,
  "version_no" integer NOT NULL,
  "parent_version_id" uuid,
  "change_summary" text,
  "created_via" text NOT NULL DEFAULT 'manual',
  "metadata" jsonb NOT NULL DEFAULT '{}'::jsonb,
  "created_by" uuid NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT "subsystem_design_versions_pk" PRIMARY KEY ("id"),
  CONSTRAINT "subsystem_design_versions_uq_0" UNIQUE ("project_id", "version_no"),
  CONSTRAINT "subsystem_design_versions_uq_1" UNIQUE ("project_id", "id"),
  CONSTRAINT "subsystem_design_versions_ck_0" CHECK (("created_via" IN ('manual', 'import', 'ai', 'copy')) IS TRUE),
  CONSTRAINT "subsystem_design_versions_ck_1" CHECK (("version_no">0) IS TRUE),
  CONSTRAINT "subsystem_design_versions_ck_2" CHECK ((jsonb_typeof("metadata")='object') IS TRUE)
);

COMMENT ON TABLE ee."subsystem_design_versions" IS '保存项目某一套完整子系统划分的版本头；条目在 subsystem_version_items。';

COMMENT ON COLUMN ee."subsystem_design_versions"."id" IS '方案版本';

COMMENT ON COLUMN ee."subsystem_design_versions"."project_id" IS '项目归属';

COMMENT ON COLUMN ee."subsystem_design_versions"."version_no" IS '方案内版本号';

COMMENT ON COLUMN ee."subsystem_design_versions"."parent_version_id" IS '从哪一版本复制/修改';

COMMENT ON COLUMN ee."subsystem_design_versions"."change_summary" IS '本次方案变化说明';

COMMENT ON COLUMN ee."subsystem_design_versions"."created_via" IS '来源';

COMMENT ON COLUMN ee."subsystem_design_versions"."metadata" IS '导入文件哈希等非核心信息';

COMMENT ON COLUMN ee."subsystem_design_versions"."created_by" IS '创建人';

COMMENT ON COLUMN ee."subsystem_design_versions"."created_at" IS '创建时间';

CREATE TABLE ee."subsystems" (
  "id" uuid NOT NULL,
  "project_id" uuid NOT NULL,
  "code" text NOT NULL,
  "created_by" uuid NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT "subsystems_pk" PRIMARY KEY ("id"),
  CONSTRAINT "subsystems_uq_0" UNIQUE ("project_id", "code"),
  CONSTRAINT "subsystems_uq_1" UNIQUE ("project_id", "id"),
  CONSTRAINT "subsystems_ck_0" CHECK ((length(btrim("code"))>0) IS TRUE)
);

COMMENT ON TABLE ee."subsystems" IS '项目内稳定的子系统身份；名称、职责随方案版本保存。';

COMMENT ON COLUMN ee."subsystems"."id" IS '子系统稳定身份';

COMMENT ON COLUMN ee."subsystems"."project_id" IS '项目归属';

COMMENT ON COLUMN ee."subsystems"."code" IS '项目内子系统编号';

COMMENT ON COLUMN ee."subsystems"."created_by" IS '创建人';

COMMENT ON COLUMN ee."subsystems"."created_at" IS '创建时间';

CREATE TABLE ee."subsystem_version_items" (
  "project_id" uuid NOT NULL,
  "design_version_id" uuid NOT NULL,
  "subsystem_id" uuid NOT NULL,
  "name" text NOT NULL,
  "description" text NOT NULL DEFAULT '''''',
  "responsibility_in" text,
  "responsibility_out" text,
  "domain_group" text,
  "is_allocatable" boolean NOT NULL DEFAULT true,
  "sort_order" integer NOT NULL DEFAULT 0,
  "source_metadata" jsonb NOT NULL DEFAULT '{}'::jsonb,
  CONSTRAINT "subsystem_version_items_pk" PRIMARY KEY ("project_id", "design_version_id", "subsystem_id"),
  CONSTRAINT "subsystem_version_items_ck_0" CHECK ((length(btrim("name"))>0) IS TRUE),
  CONSTRAINT "subsystem_version_items_ck_1" CHECK (("sort_order">=0) IS TRUE),
  CONSTRAINT "subsystem_version_items_ck_2" CHECK ((jsonb_typeof("source_metadata")='object') IS TRUE)
);

COMMENT ON TABLE ee."subsystem_version_items" IS '保存某个方案版本中子系统的名称、职责、域分组及是否可分配。';

COMMENT ON COLUMN ee."subsystem_version_items"."project_id" IS '项目归属';

COMMENT ON COLUMN ee."subsystem_version_items"."design_version_id" IS '方案版本';

COMMENT ON COLUMN ee."subsystem_version_items"."subsystem_id" IS '稳定子系统身份';

COMMENT ON COLUMN ee."subsystem_version_items"."name" IS '本版本名称';

COMMENT ON COLUMN ee."subsystem_version_items"."description" IS '本版说明；测试源缺失可为空文本并标记missing，不伪造正式职责';

COMMENT ON COLUMN ee."subsystem_version_items"."responsibility_in" IS '负责范围';

COMMENT ON COLUMN ee."subsystem_version_items"."responsibility_out" IS '不负责范围';

COMMENT ON COLUMN ee."subsystem_version_items"."domain_group" IS '域/系统分组';

COMMENT ON COLUMN ee."subsystem_version_items"."is_allocatable" IS '本版本是否允许分配';

COMMENT ON COLUMN ee."subsystem_version_items"."sort_order" IS '展示顺序';

COMMENT ON COLUMN ee."subsystem_version_items"."source_metadata" IS '导入来源行等信息';

CREATE TABLE ee."fr_allocations" (
  "artifact_id" uuid NOT NULL,
  "project_id" uuid NOT NULL,
  "function_id" uuid NOT NULL,
  "fr_id" uuid NOT NULL,
  "type_code" text NOT NULL DEFAULT 'FR_ALLOCATION',
  CONSTRAINT "fr_allocations_pk" PRIMARY KEY ("artifact_id"),
  CONSTRAINT "fr_allocations_uq_0" UNIQUE ("project_id", "function_id", "fr_id"),
  CONSTRAINT "fr_allocations_uq_1" UNIQUE ("project_id", "function_id", "artifact_id"),
  CONSTRAINT "fr_allocations_uq_2" UNIQUE ("project_id", "function_id", "artifact_id", "fr_id"),
  CONSTRAINT "fr_allocations_ck_0" CHECK ((type_code='FR_ALLOCATION') IS TRUE)
);

COMMENT ON TABLE ee."fr_allocations" IS '把FR正文与分配决定分开，表示一个FR的分配工作对象。';

COMMENT ON COLUMN ee."fr_allocations"."artifact_id" IS '分配对象ID';

COMMENT ON COLUMN ee."fr_allocations"."project_id" IS '项目归属';

COMMENT ON COLUMN ee."fr_allocations"."function_id" IS '功能归属';

COMMENT ON COLUMN ee."fr_allocations"."fr_id" IS '被分配的FR';

COMMENT ON COLUMN ee."fr_allocations"."type_code" IS '固定类型鉴别列，供组合FK校验，不是另一个可编辑属性';

CREATE TABLE ee."allocation_versions" (
  "revision_id" uuid NOT NULL,
  "project_id" uuid NOT NULL,
  "function_id" uuid NOT NULL,
  "allocation_id" uuid NOT NULL,
  "fr_id" uuid NOT NULL,
  "fr_revision_id" uuid NOT NULL,
  "design_version_id" uuid NOT NULL,
  "note" text,
  "type_code" text NOT NULL DEFAULT 'FR_ALLOCATION',
  CONSTRAINT "allocation_versions_pk" PRIMARY KEY ("revision_id"),
  CONSTRAINT "allocation_versions_uq_0" UNIQUE ("project_id", "function_id", "revision_id", "design_version_id"),
  CONSTRAINT "allocation_versions_ck_0" CHECK ((type_code='FR_ALLOCATION') IS TRUE)
);

COMMENT ON TABLE ee."allocation_versions" IS '保存某次分配依据的FR版本和子系统方案版本。';

COMMENT ON COLUMN ee."allocation_versions"."revision_id" IS '版本头ID';

COMMENT ON COLUMN ee."allocation_versions"."project_id" IS '项目归属';

COMMENT ON COLUMN ee."allocation_versions"."function_id" IS '功能归属';

COMMENT ON COLUMN ee."allocation_versions"."allocation_id" IS '分配对象';

COMMENT ON COLUMN ee."allocation_versions"."fr_id" IS 'FR对象';

COMMENT ON COLUMN ee."allocation_versions"."fr_revision_id" IS '本次分配依据的FR版本';

COMMENT ON COLUMN ee."allocation_versions"."design_version_id" IS '本次分配依据的方案版本';

COMMENT ON COLUMN ee."allocation_versions"."note" IS '分配说明';

COMMENT ON COLUMN ee."allocation_versions"."type_code" IS '固定类型鉴别列，供组合FK校验，不是另一个可编辑属性';

CREATE TABLE ee."allocation_targets" (
  "project_id" uuid NOT NULL,
  "function_id" uuid NOT NULL,
  "allocation_revision_id" uuid NOT NULL,
  "design_version_id" uuid NOT NULL,
  "subsystem_id" uuid NOT NULL,
  "rationale" text,
  CONSTRAINT "allocation_targets_pk" PRIMARY KEY ("allocation_revision_id", "subsystem_id")
);

COMMENT ON TABLE ee."allocation_targets" IS '保存某个分配版本选择的一个或多个子系统目标。';

COMMENT ON COLUMN ee."allocation_targets"."project_id" IS '项目归属';

COMMENT ON COLUMN ee."allocation_targets"."function_id" IS '功能归属';

COMMENT ON COLUMN ee."allocation_targets"."allocation_revision_id" IS '分配版本';

COMMENT ON COLUMN ee."allocation_targets"."design_version_id" IS '目标所属方案版本';

COMMENT ON COLUMN ee."allocation_targets"."subsystem_id" IS '目标子系统身份';

COMMENT ON COLUMN ee."allocation_targets"."rationale" IS '选择理由';

CREATE TABLE ee."permission_definitions" (
  "code" text NOT NULL,
  "display_name" text NOT NULL,
  "description" text,
  "resource_kind" text NOT NULL,
  "action" text NOT NULL,
  "enabled" boolean NOT NULL DEFAULT true,
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "updated_at" timestamptz NOT NULL DEFAULT now(),
  "allowed_scopes" text[] NOT NULL,
  CONSTRAINT "permission_definitions_pk" PRIMARY KEY ("code"),
  CONSTRAINT "permission_definitions_ck_0" CHECK (("resource_kind" IN ('project', 'function', 'PRD', 'UC', 'FR', 'FR_ALLOCATION', 'subsystem_design', 'view')) IS TRUE),
  CONSTRAINT "permission_definitions_ck_1" CHECK (("action" IN ('enter', 'open', 'read', 'create', 'update', 'generate', 'expand', 'accept', 'archive', 'export', 'manage_access', 'import')) IS TRUE),
  CONSTRAINT "permission_definitions_ck_2" CHECK ((cardinality(allowed_scopes)>0 AND array_position(allowed_scopes,NULL) IS NULL AND allowed_scopes <@ ARRAY['project','function','artifact']::text[]) IS TRUE),
  CONSTRAINT "permission_definitions_ck_3" CHECK ((length(btrim("code"))>0) IS TRUE),
  CONSTRAINT "permission_definitions_ck_4" CHECK ((length(btrim("display_name"))>0) IS TRUE)
);

COMMENT ON TABLE ee."permission_definitions" IS '注册后端能力点及其资源、动作和适用授权范围。';

COMMENT ON COLUMN ee."permission_definitions"."code" IS '能力编码，如 uc.read/uc.update';

COMMENT ON COLUMN ee."permission_definitions"."display_name" IS '能力名称';

COMMENT ON COLUMN ee."permission_definitions"."description" IS '能力说明';

COMMENT ON COLUMN ee."permission_definitions"."resource_kind" IS 'project/function/PRD/UC/FR/FR_ALLOCATION/subsystem_design/view；类型不是按钮DOM名';

COMMENT ON COLUMN ee."permission_definitions"."action" IS 'enter/open/read/create/update/generate/expand/accept/archive/export/manage_access/import；新增动作需受控注册';

COMMENT ON COLUMN ee."permission_definitions"."enabled" IS '能力是否启用';

COMMENT ON COLUMN ee."permission_definitions"."created_at" IS '注册时间';

COMMENT ON COLUMN ee."permission_definitions"."updated_at" IS '更新时间';

COMMENT ON COLUMN ee."permission_definitions"."allowed_scopes" IS '能力可在project/function/artifact哪些范围授予；同一uc.read可支持多个范围';

CREATE TABLE ee."access_roles" (
  "id" uuid NOT NULL,
  "code" text NOT NULL,
  "name" text NOT NULL,
  "description" text,
  "is_system" boolean NOT NULL DEFAULT true,
  "enabled" boolean NOT NULL DEFAULT true,
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "updated_at" timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT "access_roles_pk" PRIMARY KEY ("id"),
  CONSTRAINT "access_roles_uq_0" UNIQUE ("code"),
  CONSTRAINT "access_roles_ck_0" CHECK ((length(btrim("code"))>0) IS TRUE),
  CONSTRAINT "access_roles_ck_1" CHECK ((length(btrim("name"))>0) IS TRUE)
);

COMMENT ON TABLE ee."access_roles" IS '预置角色定义；一期不做角色不可变版本和批量绑定迁移。';

COMMENT ON COLUMN ee."access_roles"."id" IS '角色ID';

COMMENT ON COLUMN ee."access_roles"."code" IS '角色编码';

COMMENT ON COLUMN ee."access_roles"."name" IS '角色名称';

COMMENT ON COLUMN ee."access_roles"."description" IS '角色说明';

COMMENT ON COLUMN ee."access_roles"."is_system" IS '是否预置角色';

COMMENT ON COLUMN ee."access_roles"."enabled" IS '是否有效；禁用则所有绑定实时不再授予能力，历史绑定保留';

COMMENT ON COLUMN ee."access_roles"."created_at" IS '创建时间';

COMMENT ON COLUMN ee."access_roles"."updated_at" IS '更新时间';

CREATE TABLE ee."role_permissions" (
  "role_id" uuid NOT NULL,
  "permission_code" text NOT NULL,
  CONSTRAINT "role_permissions_pk" PRIMARY KEY ("role_id", "permission_code")
);

COMMENT ON TABLE ee."role_permissions" IS '表达角色包含哪些能力。';

COMMENT ON COLUMN ee."role_permissions"."role_id" IS '角色';

COMMENT ON COLUMN ee."role_permissions"."permission_code" IS '能力';

CREATE TABLE ee."access_bindings" (
  "id" uuid NOT NULL,
  "project_id" uuid NOT NULL,
  "user_id" uuid NOT NULL,
  "scope_kind" text NOT NULL,
  "function_id" uuid,
  "artifact_id" uuid,
  "role_id" uuid NOT NULL,
  "created_by" uuid NOT NULL,
  "updated_by" uuid NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "updated_at" timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT "access_bindings_pk" PRIMARY KEY ("id"),
  CONSTRAINT "access_bindings_ck_0" CHECK (((scope_kind='project' AND function_id IS NULL AND artifact_id IS NULL) OR (scope_kind='function' AND function_id IS NOT NULL AND artifact_id IS NULL) OR (scope_kind='artifact' AND function_id IS NOT NULL AND artifact_id IS NOT NULL)) IS TRUE),
  CONSTRAINT "access_bindings_ck_1" CHECK ((scope_kind='project') IS TRUE)
);

COMMENT ON TABLE ee."access_bindings" IS '把角色绑定到用户在项目、功能或对象的授权范围。';

COMMENT ON COLUMN ee."access_bindings"."id" IS '授权绑定ID';

COMMENT ON COLUMN ee."access_bindings"."project_id" IS '项目';

COMMENT ON COLUMN ee."access_bindings"."user_id" IS '被授权用户';

COMMENT ON COLUMN ee."access_bindings"."scope_kind" IS '授权范围';

COMMENT ON COLUMN ee."access_bindings"."function_id" IS '功能范围/对象范围';

COMMENT ON COLUMN ee."access_bindings"."artifact_id" IS '对象范围';

COMMENT ON COLUMN ee."access_bindings"."role_id" IS '角色';

COMMENT ON COLUMN ee."access_bindings"."created_by" IS '授权操作者';

COMMENT ON COLUMN ee."access_bindings"."updated_by" IS '最后修改人';

COMMENT ON COLUMN ee."access_bindings"."created_at" IS '创建时间';

COMMENT ON COLUMN ee."access_bindings"."updated_at" IS '更新时间';

CREATE TABLE ee."security_audit_events" (
  "id" uuid NOT NULL,
  "project_id" uuid,
  "actor_id" uuid,
  "subject_user_id" uuid,
  "event_type" text NOT NULL,
  "scope_kind" text,
  "function_id" uuid,
  "artifact_id" uuid,
  "before_state" jsonb,
  "after_state" jsonb,
  "reason" text,
  "request_id" text,
  "created_at" timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT "security_audit_events_pk" PRIMARY KEY ("id"),
  CONSTRAINT "security_audit_events_ck_0" CHECK (((scope_kind IS NULL AND project_id IS NULL AND function_id IS NULL AND artifact_id IS NULL) OR (scope_kind='project' AND project_id IS NOT NULL AND function_id IS NULL AND artifact_id IS NULL) OR (scope_kind='function' AND project_id IS NOT NULL AND function_id IS NOT NULL AND artifact_id IS NULL) OR (scope_kind='artifact' AND project_id IS NOT NULL AND function_id IS NOT NULL AND artifact_id IS NOT NULL)) IS TRUE),
  CONSTRAINT "security_audit_events_ck_1" CHECK ((length(btrim("event_type"))>0) IS TRUE),
  CONSTRAINT "security_audit_events_ck_2" CHECK (("before_state" IS NULL OR jsonb_typeof("before_state")='object') IS TRUE),
  CONSTRAINT "security_audit_events_ck_3" CHECK (("after_state" IS NULL OR jsonb_typeof("after_state")='object') IS TRUE)
);

COMMENT ON TABLE ee."security_audit_events" IS '记录成员、授权、撤权及敏感操作审计。';

COMMENT ON COLUMN ee."security_audit_events"."id" IS '审计事件ID';

COMMENT ON COLUMN ee."security_audit_events"."project_id" IS '项目范围；全局事件可为空';

COMMENT ON COLUMN ee."security_audit_events"."actor_id" IS '经认证的操作者；未认证失败事件可为空，不能伪造用户UUID';

COMMENT ON COLUMN ee."security_audit_events"."subject_user_id" IS '被操作用户';

COMMENT ON COLUMN ee."security_audit_events"."event_type" IS '事件类型';

COMMENT ON COLUMN ee."security_audit_events"."scope_kind" IS '经验证的事件范围；全局事件可为空';

COMMENT ON COLUMN ee."security_audit_events"."function_id" IS '功能范围';

COMMENT ON COLUMN ee."security_audit_events"."artifact_id" IS '对象范围';

COMMENT ON COLUMN ee."security_audit_events"."before_state" IS '变更前摘要';

COMMENT ON COLUMN ee."security_audit_events"."after_state" IS '变更后摘要';

COMMENT ON COLUMN ee."security_audit_events"."reason" IS '操作原因';

COMMENT ON COLUMN ee."security_audit_events"."request_id" IS '请求追踪标识';

COMMENT ON COLUMN ee."security_audit_events"."created_at" IS '发生时间';

CREATE TABLE ee."review_events" (
  "id" uuid NOT NULL,
  "project_id" uuid NOT NULL,
  "function_id" uuid NOT NULL,
  "artifact_id" uuid NOT NULL,
  "revision_id" uuid NOT NULL,
  "decision" text NOT NULL,
  "actor_id" uuid NOT NULL,
  "reason" text,
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "event_no" bigint NOT NULL,
  "request_key" text NOT NULL,
  CONSTRAINT "review_events_pk" PRIMARY KEY ("id"),
  CONSTRAINT "review_events_uq_0" UNIQUE ("artifact_id", "event_no"),
  CONSTRAINT "review_events_uq_1" UNIQUE ("artifact_id", "request_key"),
  CONSTRAINT "review_events_ck_0" CHECK (("decision" IN ('accept', 'reject', 'withdraw')) IS TRUE),
  CONSTRAINT "review_events_ck_1" CHECK (("event_no">0) IS TRUE),
  CONSTRAINT "review_events_ck_2" CHECK ((length(btrim("request_key"))>0) IS TRUE)
);

COMMENT ON TABLE ee."review_events" IS '记录谁对哪一个对象版本做了接受、拒绝或撤回决定。';

COMMENT ON COLUMN ee."review_events"."id" IS '审阅事件ID';

COMMENT ON COLUMN ee."review_events"."project_id" IS '项目归属';

COMMENT ON COLUMN ee."review_events"."function_id" IS '功能归属';

COMMENT ON COLUMN ee."review_events"."artifact_id" IS '对象';

COMMENT ON COLUMN ee."review_events"."revision_id" IS '被审版本';

COMMENT ON COLUMN ee."review_events"."decision" IS '审阅决定';

COMMENT ON COLUMN ee."review_events"."actor_id" IS '决定人';

COMMENT ON COLUMN ee."review_events"."reason" IS '原因';

COMMENT ON COLUMN ee."review_events"."created_at" IS '发生时间';

COMMENT ON COLUMN ee."review_events"."event_no" IS '持有对象行锁时递增，明确接受/拒绝事件顺序，不用时间戳猜顺序';

COMMENT ON COLUMN ee."review_events"."request_key" IS '审阅动作幂等键，相同请求重试不重复接受';

